class Solution:
    def maxXor(self, n: int, edges: List[List[int]], values: List[int]) -> int:
        import sys
        from collections import deque
        sys.setrecursionlimit(300000)
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        par = [-1]*n; order = [0]; dq = deque([0]); par[0] = 0
        children = [[] for _ in range(n)]
        while dq:
            u = dq.popleft()
            for w in g[u]:
                if w != par[u]:
                    par[w] = u; children[u].append(w); order.append(w); dq.append(w)
        ss = [0]*n; lists = [None]*n
        for u in reversed(order):
            s = values[u]; lst = [values[u]]
            for c in children[u]:
                s += ss[c]
                if len(lists[c]) > len(lst): lst, lists[c] = lists[c], lst
                lst.extend(lists[c])
            ss[u] = s; lists[u] = lst
        B = 46
        ch = [[0], [0]]; cnt = [0]
        def insert(x, d):
            cur = 0
            for b in range(B-1, -1, -1):
                bit = (x >> b) & 1
                if ch[bit][cur] == 0:
                    ch[bit][cur] = len(cnt); ch[0].append(0); ch[1].append(0); cnt.append(0)
                cur = ch[bit][cur]; cnt[cur] += d
        def query(x):
            cur = 0; res = 0
            for b in range(B-1, -1, -1):
                bit = (x >> b) & 1; want = bit ^ 1
                if ch[want][cur] and cnt[ch[want][cur]] > 0:
                    res |= 1 << b; cur = ch[want][cur]
                else:
                    cur = ch[bit][cur]
            return res
        ans = 0
        def dfs(u):
            nonlocal ans
            for c in children[u]:
                ans = max(ans, query(ss[c]))
                for x in lists[c]:
                    insert(x, 1)
                dfs(c)
        dfs(0)
        return ans

