class Solution {
public:
    int maxXor(int n, vector<vector<int>>& edges, vector<int>& values) {
        vector<vector<int>> g(n), ch(n);
        for (auto& e : edges) { g[e[0]].push_back(e[1]); g[e[1]].push_back(e[0]); }
        vector<int> par(n, -1), order; order.reserve(n);
        queue<int> q; q.push(0); par[0] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop(); order.push_back(u);
            for (int w : g[u]) if (w != par[u]) { par[w] = u; ch[u].push_back(w); q.push(w); }
        }
        vector<long long> ss(n);
        vector<vector<long long>> lists(n);
        for (int i = n-1; i >= 0; i--) {
            int u = order[i];
            ss[u] = values[u]; lists[u] = {values[u]};
            for (int c : ch[u]) {
                ss[u] += ss[c];
                if (lists[c].size() > lists[u].size()) swap(lists[u], lists[c]);
                lists[u].insert(lists[u].end(), lists[c].begin(), lists[c].end());
                vector<long long>().swap(lists[c]);
            }
        }
        const int B = 46, MAXN = n * B + 5;
        vector<array<int,2>> chT(MAXN, {0,0});
        vector<int> cnt(MAXN, 0);
        int tot = 1;
        auto insert = [&](long long x, int d) {
            int cur = 0;
            for (int b = B-1; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (!chT[cur][bit]) chT[cur][bit] = tot++;
                cur = chT[cur][bit]; cnt[cur] += d;
            }
        };
        auto query = [&](long long x) {
            int cur = 0; long long res = 0;
            for (int b = B-1; b >= 0; b--) {
                int bit = (x >> b) & 1, want = bit ^ 1;
                if (chT[cur][want] && cnt[chT[cur][want]] > 0) { res |= 1LL << b; cur = chT[cur][want]; }
                else cur = chT[cur][bit];
            }
            return res;
        };
        long long ans = 0;
        function<void(int)> dfs = [&](int u) {
            for (int c : ch[u]) {
                ans = max(ans, query(ss[c]));
                for (long long x : lists[c]) insert(x, 1);
                dfs(c);
            }
        };
        dfs(0);
        return (int)ans;
    }
};

