class Solution {
    private List<List<Integer>> ch;
    private long[] ss;
    private List<List<Long>> lists;
    private int[][] chT;
    private int[] cnt;
    private int tot = 1;
    private static final int B = 46;
    private void insert(long x, int d) {
        int cur = 0;
        for (int b = B - 1; b >= 0; b--) {
            int bit = (int)((x >> b) & 1);
            if (chT[cur][bit] == 0) chT[cur][bit] = tot++;
            cur = chT[cur][bit]; cnt[cur] += d;
        }
    }
    private long query(long x) {
        int cur = 0; long res = 0;
        for (int b = B - 1; b >= 0; b--) {
            int bit = (int)((x >> b) & 1), want = bit ^ 1;
            if (chT[cur][want] != 0 && cnt[chT[cur][want]] > 0) { res |= 1L << b; cur = chT[cur][want]; }
            else cur = chT[cur][bit];
        }
        return res;
    }
    private long ans = 0;
    private void dfs(int u) {
        for (int c : ch.get(u)) {
            ans = Math.max(ans, query(ss[c]));
            for (long x : lists.get(c)) insert(x, 1);
            dfs(c);
        }
    }
    public int maxXor(int n, int[][] edges, int[] values) {
        List<List<Integer>> g = new ArrayList<>();
        ch = new ArrayList<>();
        for (int i = 0; i < n; i++) { g.add(new ArrayList<>()); ch.add(new ArrayList<>()); }
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] par = new int[n]; Arrays.fill(par, -1);
        List<Integer> order = new ArrayList<>();
        Deque<Integer> q = new ArrayDeque<>(); q.push(0); par[0] = 0;
        while (!q.isEmpty()) {
            int u = q.pop(); order.add(u);
            for (int w : g.get(u)) if (w != par[u]) { par[w] = u; ch.get(u).add(w); q.push(w); }
        }
        ss = new long[n]; lists = new ArrayList<>();
        for (int i = 0; i < n; i++) lists.add(null);
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            ss[u] = values[u]; lists.set(u, new ArrayList<>(List.of((long) values[u])));
            for (int c : ch.get(u)) {
                ss[u] += ss[c];
                if (lists.get(c).size() > lists.get(u).size()) Collections.swap(lists, u, c);
                lists.get(u).addAll(lists.get(c));
                lists.set(c, null);
            }
        }
        chT = new int[n * B + 5][2]; cnt = new int[n * B + 5];
        dfs(0);
        return (int) ans;
    }
}

