var maxXor = function(n, edges, values) {
    const g = Array.from({length: n}, () => []), ch = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { g[a].push(b); g[b].push(a); }
    const par = new Array(n).fill(-1), order = [];
    const stack = [0]; par[0] = 0;
    while (stack.length) {
        const u = stack.pop(); order.push(u);
        for (const w of g[u]) if (w !== par[u]) { par[w] = u; ch[u].push(w); stack.push(w); }
    }
    const ss = new Array(n).fill(0), lists = new Array(n);
    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        ss[u] = values[u]; lists[u] = [BigInt(values[u])];
        for (const c of ch[u]) {
            ss[u] += ss[c];
            if (lists[c].length > lists[u].length) [lists[u], lists[c]] = [lists[c], lists[u]];
            lists[u].push(...lists[c]);
            lists[c] = null;
        }
    }
    const B = 46, cap = n * B + 5;
    const c0 = new Int32Array(cap), c1 = new Int32Array(cap), cnt = new Int32Array(cap);
    let tot = 1;
    function insert(x, d) {
        let cur = 0;
        for (let b = B - 1; b >= 0; b--) {
            const bit = Number((x >> BigInt(b)) & 1n);
            const nx = bit ? c1 : c0;
            if (!nx[cur]) nx[cur] = tot++;
            cur = nx[cur]; cnt[cur] += d;
        }
    }
    function query(x) {
        let cur = 0, res = 0n;
        for (let b = B - 1; b >= 0; b--) {
            const bit = Number((x >> BigInt(b)) & 1n), want = bit ^ 1;
            const nw = want ? c1 : c0, nb = bit ? c1 : c0;
            if (nw[cur] && cnt[nw[cur]] > 0) { res |= 1n << BigInt(b); cur = nw[cur]; }
            else cur = nb[cur];
        }
        return res;
    }
    let ans = 0n;
    function dfs(u) {
        for (const c of ch[u]) {
            const q = query(ss[c]);
            if (q > ans) ans = q;
            for (const x of lists[c]) insert(x, 1);
            dfs(c);
        }
    }
    dfs(0);
    return Number(ans);
};
